LEAVE_REQUIRED = ("leave_type", "start_date", "end_date")
CLAIM_REQUIRED = ("claim_type", "amount", "receipt_date")
FIELD_LABELS = {
    "leave_type": "Leave type",
    "start_date": "Start date",
    "end_date": "End date",
    "start_day_part": "Start day part",
    "end_day_part": "End day part",
    "claim_type": "Claim type",
    "amount": "Amount",
    "currency": "Currency",
    "receipt_date": "Receipt date",
}


@dataclass(frozen=True)
class Missing:
    field: str


@dataclass(frozen=True)
class Problem:
    field: str
    message: str


@dataclass(frozen=True)
class ValidLeave:
    draft: LeaveDraft
    days: LeaveDays
    warnings: list[str] = field(default_factory=list)


@dataclass(frozen=True)
class ValidClaim:
    draft: ClaimDraft
    warnings: list[str] = field(default_factory=list)


Outcome = Missing | Problem | ValidLeave | ValidClaim


def normalise_leave_slots(slots: LeaveSlots) -> LeaveSlots:
    """Deterministic, obviously-safe completions of the day parts.

    * single day with only one part given -> the other part mirrors it
    * a morning-only or afternoon-only start with no end date -> a single half day
      (a half day can only be a single day, so no end-date question is needed)
    """
    s = slots.model_copy()
    if s.start_date and not s.end_date and s.start_day_part in (DayPart.AM, DayPart.PM):
        s.end_date = s.start_date
        s.end_day_part = s.start_day_part
    if s.start_date and s.end_date and s.start_date == s.end_date:
        if s.start_day_part and not s.end_day_part:
            s.end_day_part = s.start_day_part
        elif s.end_day_part and not s.start_day_part:
            s.start_day_part = s.end_day_part
    return s


def _labelled_missing(present: dict[str, object], order: tuple[str, ...]) -> Missing | None:
    for name in order:
        if present.get(name) is None:
            return Missing(name)
    return None


def _day_part_problem(s: LeaveSlots) -> Problem | None:
    assert s.start_date and s.end_date
    start_part, end_part = s.start_day_part or DayPart.FULL, s.end_day_part or DayPart.FULL
    if s.start_date == s.end_date:
        if start_part != end_part:
            return Problem(
                "start_day_part",
                f"For a single day ({s.start_date.isoformat()}) the start and end day part must "
                "match. Do you want the full day, the morning only or the afternoon only?",
            )
        return None
    if start_part == DayPart.AM:
        return Problem(
            "start_day_part",
            "A leave over several days cannot start with a morning-only day. Should the first "
            "day be a full day or the afternoon only?",
        )
    if end_part == DayPart.PM:
        return Problem(
            "end_day_part",
            "A leave over several days cannot end with an afternoon-only day. Should the last "
            "day be a full day or the morning only?",
        )
    return None


def _holiday_names(session: Session, start: date, end: date) -> list[str]:
    rows = session.execute(
        select(PublicHoliday.holiday_date, PublicHoliday.name)
        .where(PublicHoliday.holiday_date >= start, PublicHoliday.holiday_date <= end)
        .order_by(PublicHoliday.holiday_date)
    ).all()
    return [f"{name} on {day.isoformat()}" for day, name in rows]


def _missing_holiday_years(session: Session, start: date, end: date) -> list[int]:
    missing: list[int] = []
    for year in range(start.year, end.year + 1):
        count = session.scalar(
            select(func.count(PublicHoliday.id)).where(
                PublicHoliday.holiday_date >= date(year, 1, 1),
                PublicHoliday.holiday_date <= date(year, 12, 31),
            )
        )
        if not count:
            missing.append(year)
    return missing


def _pydantic_problem(exc: ValidationError, labels: dict[str, str]) -> Problem:
    err = exc.errors()[0]
    loc = str(err["loc"][0]) if err["loc"] else "request"
    label = labels.get(loc, loc.replace("_", " ").capitalize())
    kind = str(err["type"])
    if "decimal" in kind or "digits" in kind:
        return Problem(loc, f"{label} is too large or has too many decimals. Please give it again.")
    text = str(err["msg"]).removeprefix("Value error, ")
    return Problem(loc, f"{label} is not valid ({text}). Please give it again.")


def validate_leave(
    session: Session,
    slots: LeaveSlots,
    *,
    employee_id: int,
    employee_email: str,
    today: date | None = None,
    editing_request_id: int | None = None,
) -> Outcome:
    today = today or today_hk()
    s = normalise_leave_slots(slots)

    if s.start_date and s.end_date and s.end_date < s.start_date:
        return Problem(
            "end_date",
            f"End date {s.end_date.isoformat()} is before the start date "
            f"{s.start_date.isoformat()}. Which end date do you want?",
        )
    if (m := _labelled_missing(s.model_dump(), LEAVE_REQUIRED)) is not None:
        return m
    assert s.leave_type and s.start_date and s.end_date  # narrowed by the missing check
    if (p := _day_part_problem(s)) is not None:
        return p

    try:
        draft = LeaveDraft(
            employee_email=employee_email,
            leave_type=s.leave_type,
            start_date=s.start_date,
            end_date=s.end_date,
            start_day_part=s.start_day_part or DayPart.FULL,
            end_day_part=s.end_day_part or DayPart.FULL,
        )
    except ValidationError as exc:
        return _pydantic_problem(exc, FIELD_LABELS)

    holidays = load_holidays(session, draft.start_date, draft.end_date)
    try:
        days = calculate_leave_days(
            draft.start_date,
            draft.end_date,
            draft.start_day_part,
            draft.end_day_part,
            holidays,
        )
    except LeaveCalculationError:
        span = (
            draft.start_date.isoformat()
            if draft.start_date == draft.end_date
            else f"{draft.start_date.isoformat()} to {draft.end_date.isoformat()}"
        )
        names = _holiday_names(session, draft.start_date, draft.end_date)
        why = "only weekends" + (f" and public holidays ({'; '.join(names)})" if names else "")
        return Problem(
            "start_date",
            f"{span} covers {why}, so it contains no working day to take as leave. "
            "Which working dates do you want?",
        )

    violation = first_violation(
        RuleContext(
            session=session,
            employee_id=employee_id,
            request_type=RequestType.LEAVE,
            draft=draft,
            today=today,
            days=days,
            editing_request_id=editing_request_id,
        )
    )
    if violation is not None:
        return Problem(violation.field, violation.message)

    warnings = [
        f"No public-holiday data for {year}; only weekends were excluded from the working days"
        for year in _missing_holiday_years(session, draft.start_date, draft.end_date)
    ]
    return ValidLeave(draft=draft, days=days, warnings=warnings)


def _amount_problem(amount: Decimal) -> Problem | None:
    if not amount.is_finite():
        return Problem("amount", "That amount is not a number. How much is the claim, in HKD?")
    if amount <= 0:
        return Problem(
            "amount",
            f"The amount {format(amount, 'f')} must be greater than 0. "
            "How much is the claim, in HKD?",
        )
    exponent = amount.as_tuple().exponent
    if isinstance(exponent, int) and exponent < -CLAIM_MAX_DECIMALS:
        return Problem(
            "amount",
            f"The amount {format(amount, 'f')} has more than {CLAIM_MAX_DECIMALS} decimal "
            "places. What is the exact amount in HKD (at most 2 decimals)?",
        )
    return None


def validate_claim(
    session: Session,
    slots: ClaimSlots,
    *,
    employee_id: int,
    employee_email: str,
    today: date | None = None,
    editing_request_id: int | None = None,
) -> Outcome:
    today = today or today_hk()

    if slots.amount is not None and (p := _amount_problem(slots.amount)) is not None:
        return p
    currency = (slots.currency or CLAIM_CURRENCY).strip().upper()
    if currency != CLAIM_CURRENCY:
        return Problem(
            "currency",
            f"Claims are accepted in {CLAIM_CURRENCY} only, and you mentioned {currency}. "
            "What is the amount in HKD?",
        )
    if slots.receipt_date is not None and slots.receipt_date > today:
        return Problem(
            "receipt_date",
            f"The receipt date {slots.receipt_date.isoformat()} is in the future. "
            "What is the date on the receipt?",
        )
    if (m := _labelled_missing(slots.model_dump(), CLAIM_REQUIRED)) is not None:
        return m
    assert slots.claim_type and slots.amount is not None and slots.receipt_date

    try:
        draft = ClaimDraft(
            employee_email=employee_email,
            claim_type=slots.claim_type,
            amount=slots.amount,
            currency=CLAIM_CURRENCY,
            receipt_date=slots.receipt_date,
        )
    except ValidationError as exc:
        return _pydantic_problem(exc, FIELD_LABELS)

    violation = first_violation(
        RuleContext(
            session=session,
            employee_id=employee_id,
            request_type=RequestType.CLAIM,
            draft=draft,
            today=today,
            amount=draft.amount,
            editing_request_id=editing_request_id,
        )
    )
    if violation is not None:
        return Problem(violation.field, violation.message)
    return ValidClaim(draft=draft)


def to_decimal(value: float | int | str) -> Decimal | None:
    """LLM ``amount`` (float) -> exact Decimal through its shortest repr (12.3, not 12.3000...01).

    Returns None when it is not a finite number (NaN / infinity). More than 2 decimals is NOT
    rounded here: the value is kept so that validation can tell the user.
    """

    try:
        result = Decimal(str(value))
    except (InvalidOperation, ValueError):
        return None
    return result if result.is_finite() else None


def coerce_enum[E: (LeaveType, ClaimType, DayPart)](enum_cls: type[E], value: object) -> E | None:
    try:
        return enum_cls(value)
    except ValueError:
        return None
"""Tunable constants and the Phase 3 business-rule extension point.

Phase 2 enforces STRUCTURAL validity (it is what makes a request meaningful):

* enums / types, ``end_date >= start_date``, valid half-day part combinations
* at least one working day (weekend-only / holiday-only ranges are errors)
* claim amount > 0 with at most 2 decimals (more is rejected, never rounded), HKD only,
  receipt date not in the future (``ClaimDraft``)
* ownership and the status state machine for update / cancel

plus exactly one business rule, ``no_past_leave_except_sick`` (registered below). Every other
business rule (maximum length, overlap with other leave, leave balance, claim caps, receipt age,
duplicate claims, ...) is deliberately NOT implemented yet: Ken schedules them for Phase 3.
They plug in here without touching the agent or the workflow:

    from app.chat.policy import BUSINESS_RULES, RuleContext, Violation

    def no_leave_over_60_days(ctx: RuleContext) -> Violation | None:
        if ctx.request_type is RequestType.LEAVE and ctx.days and ctx.days.calendar_days > 60:
            return Violation("end_date", "Leave can cover at most 60 calendar days. ...")
        return None

    BUSINESS_RULES.append(no_leave_over_60_days)

Every rule runs after the structural checks (and again when the user presses Confirm, because
the world may have changed). The FIRST violation becomes a deterministic follow-up question and
no confirmation card is shown until the user fixes it. The registry ships with the single
rule ``no_past_leave_except_sick``.
"""

from collections.abc import Callable, Sequence
from dataclasses import dataclass
from datetime import date
from decimal import Decimal

from sqlalchemy.orm import Session

from app.chat.format import fmt_date
from app.db.models import LeaveRequest
from app.domain.enums import LeaveType, RequestStatus, RequestType
from app.domain.leave import LeaveDays
from app.schemas.drafts import ClaimDraft, LeaveDraft

# --- structural limits (documented in backend/README.md) -------------------------------------
CLAIM_MAX_DECIMALS = 2
CLAIM_CURRENCY = "HKD"

# Statuses in which an employee may still change or cancel a request (not yet reviewed).
EDITABLE_STATUSES = frozenset(
    {RequestStatus.DRAFT, RequestStatus.SUBMISSION_FAILED, RequestStatus.PENDING_APPROVAL}
)
# Statuses that can be (re)submitted to the mock API.
RETRYABLE_STATUSES = frozenset({RequestStatus.DRAFT, RequestStatus.SUBMISSION_FAILED})

# --- LLM / conversation handling -------------------------------------------------------------
LLM_MIN_CONFIDENCE = 0.5  # below this (or with ambiguities) no card is shown
FOLLOWUP_MAX_CHARS = 240  # an LLM-worded question longer than this is ignored
HISTORY_MESSAGES = 8  # recent messages sent to the LLM as context
HISTORY_MESSAGE_CHARS = 500
OPEN_REQUESTS_LIMIT = 10  # of THIS user's editable requests, given to the LLM
STATUS_LIST_LIMIT = 10  # most recent requests in a status card
TITLE_MAX_CHARS = 60


# --- Phase 3 extension point -----------------------------------------------------------------
@dataclass(frozen=True)
class RuleContext:
    """Everything a business rule may look at (already structurally valid)."""

    session: Session
    employee_id: int
    request_type: RequestType
    draft: LeaveDraft | ClaimDraft
    today: date
    days: LeaveDays | None = None  # leave only: calendar / working days
    amount: Decimal | None = None  # claim only
    editing_request_id: int | None = None  # exclude this request from overlap / duplicate checks


@dataclass(frozen=True)
class Violation:
    """A user-facing rule violation: the field to fix and a complete follow-up sentence."""

    field: str
    message: str


Rule = Callable[[RuleContext], "Violation | Sequence[Violation] | None"]


def no_past_leave_except_sick(ctx: RuleContext) -> Violation | None:
    """Only sick leave may start in the past (any number of days back).

    Annual, personal and unpaid leave must start today or later (Hong Kong date). When an
    existing request is being edited the rule applies only if its start date or leave type is
    changed, so shortening or extending an already-started leave is not blocked by its old
    start date.
    """
    draft = ctx.draft
    if not isinstance(draft, LeaveDraft):
        return None
    if draft.leave_type == LeaveType.SICK or draft.start_date >= ctx.today:
        return None
    if ctx.editing_request_id is not None:
        stored = ctx.session.get(LeaveRequest, ctx.editing_request_id)
        if (
            stored is not None
            and stored.start_date == draft.start_date
            and stored.leave_type == draft.leave_type
        ):
            return None
    return Violation(
        "start_date",
        f"{draft.leave_type.value.title()} leave cannot start in the past (today is "
        f"{fmt_date(ctx.today)}). Which start date do you want? Sick leave can be back-dated.",
    )


BUSINESS_RULES: list[Rule] = [no_past_leave_except_sick]


def first_violation(ctx: RuleContext, rules: Sequence[Rule] | None = None) -> Violation | None:
    """Run the registered rules in order and return the first violation (None = all pass)."""
    for rule in BUSINESS_RULES if rules is None else rules:
        result = rule(ctx)
        if result is None:
            continue
        if isinstance(result, Violation):
            return result
        for violation in result:
            return violation
    return None

"""Shared structured-output plumbing for the LLM providers (Gemini, Ollama, ...).

The thin wire schema (dates as ISO strings, no constraints) is what a model is asked to
produce; ``parse_turn`` normalises it defensively and validates it with ``AgentTurn``.
"""

from __future__ import annotations

import json
import re
from collections.abc import Mapping, Sequence
from datetime import datetime
from typing import Any

from pydantic import BaseModel, ConfigDict, ValidationError

from app.domain.enums import ClaimType, DayPart, LeaveType, RequestStatus, RequestType
from app.llm.schemas import AgentTurn, DocType, DocumentExtraction, Intent

ATTACHMENT_MIME_TYPES = frozenset(
    {"image/jpeg", "image/png", "image/webp", "image/heic", "image/heif", "application/pdf"}
)


# --- Thin wire schema: what Gemini is asked to produce (dates as ISO strings, no constraints) ---
class _WireLeave(BaseModel):
    model_config = ConfigDict(extra="ignore")

    leave_type: LeaveType | None = None
    start_date: str | None = None
    end_date: str | None = None
    start_day_part: DayPart | None = None
    end_day_part: DayPart | None = None


class _WireClaim(BaseModel):
    model_config = ConfigDict(extra="ignore")

    claim_type: ClaimType | None = None
    amount: float | None = None
    currency: str | None = None
    receipt_date: str | None = None


class _WireRef(BaseModel):
    model_config = ConfigDict(extra="ignore")

    request_id: int | None = None
    request_type: RequestType | None = None
    hint: str | None = None


class _WireStatusQuery(BaseModel):
    model_config = ConfigDict(extra="ignore")

    request_type: RequestType | None = None
    request_id: int | None = None
    status: RequestStatus | None = None


class _WireDocument(BaseModel):
    model_config = ConfigDict(extra="ignore")

    index: int = 0
    doc_type: DocType
    readable: bool = True
    summary: str | None = None
    person_name: str | None = None
    provider_name: str | None = None
    issue_date: str | None = None
    rest_start_date: str | None = None
    rest_end_date: str | None = None
